const MENU_CONFIG=[{path:"/",name:"Inicio",order:0},{path:"/about",name:"Sobre M\xed",order:1},{path:"/formacion",name:"Formaci\xf3n",order:2},{path:"/proyectos",name:"Proyectos",order:3},{path:"/homelab",name:"Homelab",order:4},{path:"/contacto",name:"Contacto",order:5}];class RoutingHelpers{static getMenuOrder(){return MENU_CONFIG}static getCurrentPageInfo(){const t=window.location.pathname;return MENU_CONFIG.find(e=>e.path===t)||MENU_CONFIG[0]}static getPageByPath(t){return MENU_CONFIG.find(e=>e.path===t)}static getNavigationDirection(t,e){const a=MENU_CONFIG.find(e=>e.path===t),i=MENU_CONFIG.find(t=>t.path===e);return a&&i?i.order>a.order?"right":"left":"right"}static getNextPage(t){const e=MENU_CONFIG.find(e=>e.path===t);if(!e)return MENU_CONFIG[0];const a=(e.order+1)%MENU_CONFIG.length;return MENU_CONFIG[a]}static getPreviousPage(t){const e=MENU_CONFIG.find(e=>e.path===t);if(!e)return MENU_CONFIG[0];const a=0===e.order?MENU_CONFIG.length-1:e.order-1;return MENU_CONFIG[a]}static isValidMenuPath(t){return MENU_CONFIG.some(e=>e.path===t)}static addKeyboardShortcuts(){this._keyboardListenerAdded||(this._keyboardListenerAdded=!0,document.addEventListener("keydown",t=>{if(!this.isInputFocused())switch(t.key){case"ArrowRight":case"j":t.preventDefault(),this.navigateNext();break;case"ArrowLeft":case"k":t.preventDefault(),this.navigatePrevious();break;case"Home":t.preventDefault(),this.navigateToHome();break;case"1":case"2":case"3":case"4":case"5":case"6":(t.ctrlKey||t.metaKey)&&(t.preventDefault(),this.navigateToIndex(parseInt(t.key)-1))}}))}static isInputFocused(){const t=document.activeElement;return t&&("INPUT"===t.tagName||"TEXTAREA"===t.tagName||"true"===t.contentEditable||"SELECT"===t.tagName)}static navigateNext(){const t=this.getNextPage(window.location.pathname);this.triggerNavigation(t.path)}static navigatePrevious(){const t=this.getPreviousPage(window.location.pathname);this.triggerNavigation(t.path)}static navigateToHome(){this.triggerNavigation("/")}static navigateToIndex(t){t>=0&&t<MENU_CONFIG.length&&this.triggerNavigation(MENU_CONFIG[t].path)}static triggerNavigation(t){if(!t||!this.isValidMenuPath(t))return void console.warn("Ruta inv\xe1lida para navegaci\xf3n:",t);const e=new CustomEvent("requestPageTransition",{detail:{targetPath:t}});document.dispatchEvent(e)}}export{RoutingHelpers};